  "preferred_configuration": {
    "prize_parts": [
      {
        "ballot_id": "B001",
        "laureates": [
          "Hidetoshi Katori",
          "Jun Ye"
        ],
        "citation": "For the development and realization of optical lattice clocks, enabling extraordinary precision in timekeeping and new tests of fundamental physics."
      }
    ]
  },
  "alternatives": [
    "B004",
    "B020"
  ],
  "statement": {
    "case_for": "Optical lattice clocks turned optical-frequency standards into exceptionally precise and reproducible measurement instruments. Their performance has been demonstrated across laboratories, and their reach into tests of fundamental physics and geodesy gives the advance significance beyond timekeeping. Katori and Ye made complementary contributions to the clock architecture and its experimental realization, supporting a focused citation and attribution.",
    "case_against": "Clock performance has advanced through many groups, and the boundary between the foundational architecture and later precision improvements needs careful historical assessment. The field is still developing, so the committee should make clear that it is recognizing the established clock advance rather than claiming every later application or improvement.",
    "responses": [
      {
        "member_id": "johansson-goran",
        "point": "Johansson argues that the boundary between foundational clock physics and incremental precision advances is difficult to draw, even though the technology has been widely realized and its scientific uses demonstrated.",
        "response": "I agree that the citation must identify the foundational clock advance rather than absorb the whole metrology program. The repeated realization of the approach helps make that boundary defensible: it shows that the achievement is a reproducible instrument concept, not a single record measurement."
      },
      {
        "member_id": "pearce-mark",
        "point": "Pearce notes that the core achievement is well established and scientifically far-reaching, while asking how to distinguish the original invention from later performance advances and applications.",
        "response": "That distinction is central to attribution. Katori and Ye represent complementary contributions to the architecture and its realization; the citation should stop there. Later comparisons and applications demonstrate the clocks' reach, but need not be treated as part of the prize claim."
      }
    ],
    "uncertainties": [
      "A historical assessment is needed to define the awardable foundational contributions relative to earlier clock concepts and the later international effort that improved performance."
    ],
    "conflict_note": "None apparent from the supplied profile."
  }
}
